import heapq

def minActivationCost(edges: list[list[int]], values: list[int]) -> int:
    n = len(values)
    adj = [[] for _ in range(n)]
    for u, v, c in edges:
        adj[u].append((v, c))
        adj[v].append((u, c))

    start_par = values[0].bit_count() % 2
    dist = [[float('inf')] * 2 for _ in range(n)]
    dist[0][start_par] = 0
    pq = [(0, 0, start_par)]

    while pq:
        d, u, p = heapq.heappop(pq)
        if d > dist[u][p]:
            continue
        if u == n - 1 and p == 0:
            return d
        for v, c in adj[u]:
            np = (p ^ (values[v].bit_count() % 2))
            if d + c < dist[v][np]:
                dist[v][np] = d + c
                heapq.heappush(pq, (d + c, v, np))
    return dist[n - 1][0] if dist[n - 1][0] != float('inf') else -1

#include <vector>
#include <queue>

class Solution {
public:
    int minActivationCost(std::vector<std::vector<int>>& edges, std::vector<int>& values) {
        int n = values.size();
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (auto const& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        int start_par = __builtin_popcount(values[0]) % 2;
        std::vector<std::vector<int>> dist(n, std::vector<int>(2, 1e9));
        dist[0][start_par] = 0;
        std::priority_queue<std::vector<int>, std::vector<std::vector<int>>, std::greater<std::vector<int>>> pq;
        pq.push({0, 0, start_par});
        while (!pq.empty()) {
            auto cur = pq.top(); pq.pop();
            int d = cur[0], u = cur[1], p = cur[2];
            if (d > dist[u][p]) continue;
            if (u == n - 1 && p == 0) return d;
            for (auto const& edge : adj[u]) {
                int v = edge.first, c = edge.second;
                int np = p ^ (__builtin_popcount(values[v]) % 2);
                if (d + c < dist[v][np]) {
                    dist[v][np] = d + c;
                    pq.push({d + c, v, np});
                }
            }
        }
        return dist[n - 1][0] == 1e9 ? -1 : dist[n - 1][0];
    }
};

import java.util.*;

class Solution {
    public int minActivationCost(int[][] edges, int[] values) {
        int n = values.length;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }
        int startPar = Integer.bitCount(values[0]) % 2;
        int[][] dist = new int[n][2];
        for (int i = 0; i < n; i++) Arrays.fill(dist[i], Integer.MAX_VALUE);
        dist[0][startPar] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, 0, startPar});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1], p = cur[2];
            if (d > dist[u][p]) continue;
            if (u == n - 1 && p == 0) return d;
            for (int[] edge : adj[u]) {
                int v = edge[0], c = edge[1];
                int np = p ^ (Integer.bitCount(values[v]) % 2);
                if (d + c < dist[v][np]) {
                    dist[v][np] = d + c;
                    pq.offer(new int[]{d + c, v, np});
                }
            }
        }
        return dist[n - 1][0] == Integer.MAX_VALUE ? -1 : dist[n - 1][0];
    }
}

var minActivationCost = function(edges, values) {
    const n = values.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, c] of edges) {
        adj[u].push([v, c]);
        adj[v].push([u, c]);
    }
    const popcount = (x) => {
        let count = 0;
        while (x > 0) { count += x & 1; x >>= 1; }
        return count;
    };
    const startPar = popcount(values[0]) % 2;
    const dist = Array.from({ length: n }, () => [Infinity, Infinity]);
    dist[0][startPar] = 0;
    const pq = [[0, 0, startPar]];
    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u, p] = pq.shift();
        if (d > dist[u][p]) continue;
        if (u === n - 1 && p === 0) return d;
        for (const [v, c] of adj[u]) {
            const np = p ^ (popcount(values[v]) % 2);
            if (d + c < dist[v][np]) {
                dist[v][np] = d + c;
                pq.push([d + c, v, np]);
            }
        }
    }
    return dist[n - 1][0] === Infinity ? -1 : dist[n - 1][0];
};
